export function rareLabel(count: number): string {
	const lang = displayLanguage();
	if (/^(brazilian|portuguese)/.test(lang)) return `${count} ${count === 1 ? 'rara' : 'raras'}`;
	if (/^(spanish|latam)/.test(lang)) return `${count} ${count === 1 ? 'rara' : 'raras'}`;
	if (/^french/.test(lang)) return `${count} ${count === 1 ? 'rare' : 'rares'}`;
	if (/^german/.test(lang)) return `${count} selten`;
	return `${count} rare`;
}

/** Fundo e troféu do cabeçalho completo. icons: ícones das conquistas (repetidos até encher o mosaico de 10 x 7). */
export function perfectBackdropHtml(icons: string[]): string {
	const id = `gdl-lam-perfect-${++seq}`;
	const list = icons.filter(Boolean);
	const tiles: string[] = [];
	if (list.length) for (let i = 0; i < 70; i++) tiles.push(`<image href="${escapeHtml(list[i % list.length])}" x="${(i % 10) * 64}" y="${Math.floor(i / 10) * 64}" width="64" height="64"></image>`);
	const stars = SCALES.map((scale, i) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#1a9fff" class="gdl-lam-perfect-star" style="--delay:${(0.025 + i * 0.05).toFixed(3)};--scale:${scale};left:${(i * 37 + 7) % 96}%;top:${8 + ((i * 53) % 78)}%" width="16" height="16">${STAR}</svg>`).join('');
	return `<div class="gdl-lam-perfect-bg" aria-hidden="true">${tiles.length ? `<svg class="gdl-lam-perfect-tiles"><defs><pattern id="${id}" patternUnits="userSpaceOnUse" width="640" height="448">${tiles.join('')}</pattern></defs><rect width="100%" height="100%" fill="url(#${id})"></rect></svg>` : ''}<div class="gdl-lam-perfect-stars">${stars}</div></div>`;
}

export function perfectAwardHtml(): string {
	const id = `gdl-lam-award-${++seq}`;
	const sparkles = SPARKLES.map(p => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" class="gdl-lam-sparkle" style="--sparkle-x:${p.x}%;--sparkle-y:${p.y}%;--sparkle-delay:${p.d};--sparkle-size:${p.s}px">${STAR}</svg>`).join('');
	return `<span class="gdl-lam-award" style="--award-base:40px"><span class="gdl-lam-award-icon">${awardSvg(id)}</span><span class="gdl-lam-sparkles" aria-hidden="true">${sparkles}</span></span>`;
}

export const perfectCss = (scope: string): string => `
	${scope} .gdl-lam-progressbox.is-perfect { height: auto !important; min-height: 84px !important; padding: 18px 20px !important; display: flex !important; align-items: center !important; gap: 16px !important; background: linear-gradient(90deg, rgba(26, 159, 255, .16), rgba(103, 112, 123, .2) 60%) !important; isolation: isolate; }
	${scope} .gdl-lam-progressbox.is-perfect > :not(.gdl-lam-perfect-bg) { position: relative !important; z-index: 1 !important; }
	${scope} .gdl-lam-perfect-bg { position: absolute !important; inset: 0 !important; z-index: 0 !important; pointer-events: none !important; }
	${scope} .gdl-lam-perfect-tiles { position: absolute !important; left: 0; top: 0; width: calc(100% + 640px) !important; height: 100% !important; opacity: .16; filter: saturate(.8); animation: gdl-lam-tiles 60s linear infinite; -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 35%, #000 100%); mask-image: linear-gradient(90deg, transparent 0, #000 35%, #000 100%); }
	@keyframes gdl-lam-tiles { from { transform: translateX(0); } to { transform: translateX(-640px); } }
	${scope} .gdl-lam-perfect-stars { position: absolute !important; inset: 0 !important; }
	${scope} .gdl-lam-perfect-star { position: absolute !important; width: 16px !important; height: 16px !important; opacity: 0; transform: scale(0); animation: gdl-lam-twinkle 3.2s ease-in-out infinite; animation-delay: calc(var(--delay) * 3.2s); filter: drop-shadow(0 0 4px rgba(26, 159, 255, .9)); }
	@keyframes gdl-lam-twinkle { 0%, 100% { opacity: 0; transform: scale(0) rotate(0deg); } 45% { opacity: .9; transform: scale(calc(.35 + var(--scale) * .65)) rotate(45deg); } 60% { opacity: .9; transform: scale(calc(.35 + var(--scale) * .65)) rotate(60deg); } }
	${scope} .gdl-lam-award { position: relative !important; flex: 0 0 auto !important; display: inline-flex !important; width: calc(var(--award-base) * .75) !important; height: var(--award-base) !important; overflow: visible !important; }
	${scope} .gdl-lam-award-icon, ${scope} .gdl-lam-award-icon svg { display: block !important; width: 100% !important; height: 100% !important; overflow: visible !important; }
	${scope} .gdl-lam-award-icon svg { filter: drop-shadow(0 0 8px rgba(26, 159, 255, .55)); animation: gdl-lam-award-glow 2.6s ease-in-out infinite; }
	@keyframes gdl-lam-award-glow { 0%, 100% { filter: drop-shadow(0 0 5px rgba(26, 159, 255, .45)); } 50% { filter: drop-shadow(0 0 12px rgba(71, 191, 255, .95)); } }
	${scope} .gdl-lam-award-shine-bar { animation: gdl-lam-shine 2.8s ease-in-out infinite; }
	@keyframes gdl-lam-shine { 0% { transform: translateX(-48px); } 55%, 100% { transform: translateX(16px); } }
	${scope} .gdl-lam-sparkles { position: absolute !important; inset: -6px !important; overflow: visible !important; pointer-events: none !important; color: #c7ecff; }
	${scope} .gdl-lam-sparkle { position: absolute !important; left: var(--sparkle-x); top: var(--sparkle-y); width: var(--sparkle-size) !important; height: var(--sparkle-size) !important; margin: calc(var(--sparkle-size) / -2) 0 0 calc(var(--sparkle-size) / -2); opacity: 0; animation: gdl-lam-sparkle 1.8s ease-in-out infinite; animation-delay: calc(var(--sparkle-delay) * 1.8s); filter: drop-shadow(0 0 3px #fff); }
	@keyframes gdl-lam-sparkle { 0%, 100% { opacity: 0; transform: scale(.2) rotate(0deg); } 40% { opacity: 1; transform: scale(1) rotate(30deg); } 70% { opacity: 0; transform: scale(.4) rotate(70deg); } }
	${scope} .gdl-lam-perfect-rare { color: #ffc82c !important; flex-shrink: 0 !important; text-transform: none !important; }
	${scope} .gdl-lam-progressbox.is-perfect .gdl-lam-fill { background: linear-gradient(90deg, #47bfff, #1a9fff) !important; box-shadow: 0 0 8px rgba(26, 159, 255, .7) !important; }
	@media (prefers-reduced-motion: reduce) { ${scope} .gdl-lam-perfect-tiles, ${scope} .gdl-lam-perfect-star, ${scope} .gdl-lam-award-icon svg, ${scope} .gdl-lam-award-shine-bar, ${scope} .gdl-lam-sparkle { animation: none !important; } ${scope} .gdl-lam-perfect-star { opacity: .6; transform: scale(var(--scale)); } }
`;
